def readback():
 run=load(OUT/'run.json');copy=dict(run);copy.pop('run_sha256');assert sha(compact(copy))==run['run_sha256']
 assert sha((OUT/'named-repository-review.payload.json').read_bytes())==run['distinct_complete_named_RAW_payload_sha256']
 checkpins(load(OUT/'output.manifest.json')['artifacts'])
 assert git('rev-parse','HEAD')==COMMIT
 print(json.dumps({'status':'READ_ONLY_CANDIDATE_BINDINGS_PASS','actual_pid':os.getpid(),'checked_commit':COMMIT,'whole_logical_run_sha256':run['run_sha256'],'distinct_complete_named_RAW_payload_sha256':run['distinct_complete_named_RAW_payload_sha256']}))
def close():
 readback()
 for n in ['finalizer/process.receipt.json','readback/process.receipt.json']:
  r=load(OUT/n);assert r['exit_code']==0 and r['terminal_closed']
 lease=load(OUT/'proposed-lease.closed.json');lease['actual_foreground_finalizer']=rawpin(OUT/'finalizer/process.receipt.json');lease['actual_foreground_readback']=rawpin(OUT/'readback/process.receipt.json');lease['actual_final_closure_pid']=os.getpid();lease['complete_owned_output_manifest_after_terminal_readback']=artifacts(['lease.json'])
 print(json.dumps({'status':'CLOSED_LAST_FINAL_WRITE_NOW','actual_pid':os.getpid(),'owned_outputs_bound_excluding_lease':len(lease['complete_owned_output_manifest_after_terminal_readback'])}));sys.stdout.flush()
 write('lease.json',lease)
